INSERT INTO recipes
  (title, description, category, prep_minutes, cook_minutes, servings, ingredients, instructions, is_starter)
VALUES
('Classic Margherita Pizza', 'Traditional Italian pizza with fresh mozzarella, basil, and tomato sauce.', 'Dinner', 20, 15, 2, '2 cups flour\n1 tbsp yeast\n1 cup water\n500g mozzarella\n200g tomato sauce\n20 fresh basil leaves\nSalt and olive oil', 'Mix flour, yeast, and water to form dough.\nLet rise for 1 hour.\nSpread tomato sauce on dough.\nAdd mozzarella and basil.\nBake at 220°C for 15 minutes.', 1),
('Spaghetti Carbonara', 'Creamy Roman pasta with bacon, eggs, and parmesan cheese.', 'Dinner', 10, 20, 4, '400g spaghetti\n200g pancetta\n4 eggs\n100g parmesan\nBlack pepper\nSalt', 'Cook spaghetti in salted boiling water.\nDice and fry pancetta.\nMix eggs with grated parmesan.\nToss hot pasta with pancetta and egg mixture.\nSeason with pepper.', 1),
('Chicken Tikka Masala', 'Spiced Indian chicken in creamy tomato sauce, served with rice.', 'Dinner', 15, 35, 4, '800g chicken breast\n200g yogurt\n3 tbsp tikka paste\n400ml coconut milk\n400g canned tomatoes\n2 onions\n3 cloves garlic\nCilantro\nRice', 'Marinate chicken in yogurt and tikka paste for 2 hours.\nCook chicken in a pan until golden.\nSauté onions and garlic.\nAdd tomatoes and coconut milk.\nSimmer for 20 minutes. Serve with rice and cilantro.', 1),
('Chocolate Chip Cookies', 'Classic chewy cookies loaded with chocolate chips.', 'Dessert', 15, 12, 24, '225g butter\n200g brown sugar\n100g white sugar\n2 eggs\n2 tsp vanilla\n280g flour\n1 tsp baking soda\n1 tsp salt\n340g chocolate chips', 'Cream butter and sugars.\nBeat in eggs and vanilla.\nMix flour, baking soda, and salt.\nCombine wet and dry ingredients.\nFold in chocolate chips.\nBake at 190°C for 12 minutes.', 1),
('Caesar Salad', 'Crisp romaine lettuce with parmesan, croutons, and tangy Caesar dressing.', 'Salad', 10, 0, 4, '1 head romaine lettuce\n100g parmesan\n200g croutons\n3 tbsp mayonnaise\n2 cloves garlic\n1 tbsp lemon juice\n1 tsp Worcestershire sauce\nAnchovies (optional)', 'Whisk mayonnaise, garlic, lemon juice, and Worcestershire.\nTear romaine lettuce.\nToss with dressing.\nTop with parmesan and croutons.', 1),
('Beef Tacos', 'Seasoned ground beef in soft tortillas with fresh toppings.', 'Dinner', 15, 15, 4, '500g ground beef\n2 tbsp taco seasoning\n8 flour tortillas\n100g cheddar\n100g sour cream\n2 tomatoes\n1 onion\nLettuce\nSalsa', 'Brown ground beef in a skillet.\nAdd taco seasoning and water, simmer 10 minutes.\nWarm tortillas.\nFill with beef, cheese, and toppings.\nServe with salsa and sour cream.', 1),
('Greek Salad', 'Fresh Mediterranean salad with feta cheese, olives, and tomatoes.', 'Salad', 15, 0, 4, '4 tomatoes\n1 cucumber\n200g feta cheese\n100g black olives\n1 red onion\n3 tbsp olive oil\n1 tbsp balsamic vinegar\nOregano', 'Chop tomatoes and cucumber.\nDice feta cheese.\nCombine vegetables in a bowl.\nWhisk olive oil and vinegar.\nToss salad with dressing and oregano.', 1),
('Pad Thai', 'Stir-fried rice noodles with shrimp, tofu, and peanuts.', 'Dinner', 20, 10, 4, '300g rice noodles\n250g shrimp\n200g tofu\n100g roasted peanuts\n3 eggs\n2 cloves garlic\n3 tbsp tamarind paste\n2 tbsp fish sauce\n1 tbsp lime juice\nBean sprouts', 'Soak rice noodles in warm water.\nStir-fry shrimp and tofu.\nAdd noodles and sauce.\nPush to the side, scramble eggs.\nToss together and serve with peanuts and bean sprouts.', 1),
('Pancakes', 'Fluffy buttermilk pancakes perfect for breakfast.', 'Breakfast', 10, 15, 4, '200g flour\n2 tbsp sugar\n2 tsp baking powder\n1 tsp salt\n250ml buttermilk\n2 eggs\n2 tbsp melted butter\nMaple syrup', 'Mix flour, sugar, baking powder, and salt.\nWhisk buttermilk, eggs, and butter.\nCombine wet and dry ingredients.\nCook on griddle until golden on both sides.\nServe with maple syrup.', 1),
('Tomato Soup', 'Creamy tomato soup with fresh basil and croutons.', 'Soup', 10, 25, 4, '800g canned tomatoes\n1 onion\n3 cloves garlic\n200ml heavy cream\n500ml vegetable broth\n20 fresh basil leaves\nOlive oil\nSalt and pepper', 'Sauté onion and garlic in olive oil.\nAdd tomatoes and broth, simmer 20 minutes.\nBlend until smooth.\nStir in cream and basil.\nSeason with salt and pepper.', 1),
